function irParaTela(tela, pushHistory) {
      if (pushHistory === undefined) pushHistory = true;
      document.getElementById("welcome-screen").style.display = "none";
      document.getElementById("tutorial-screen").classList.remove("open");
      document.getElementById("portarias-screen").classList.remove("open");
      document.getElementById("regras-screen").classList.remove("open");
      document.getElementById("comparativo-screen").classList.remove("open");
      document.getElementById("cursos-screen").classList.remove("open");
      switch (tela) {
        case "welcome":
          document.getElementById("welcome-screen").style.display = "flex";
          break;
        case "panel":
          break;
        case "tutorials":
          document.getElementById("tutorial-screen").classList.add("open");
          initTutorialsScreen();
          break;
        case "portarias":
          document.getElementById("portarias-screen").classList.add("open");
          break;
        case "regras":
          document.getElementById("regras-screen").classList.add("open");
          initRegras();
          break;
        case "comparativo":
          document.getElementById("comparativo-screen").classList.add("open");
          renderComparativoTable();
          break;
        case "cursos":
          document.getElementById("cursos-screen").classList.add("open");
          initCursosScreen();
          break;
      }
      if (pushHistory) {
        history.pushState({ tela: tela }, "");
      }
      try { sessionStorage.setItem("ibrep_tela_atual", tela); } catch (e) {}
    }
    function openPanel() { if (!exigirPermissao("painel")) return; irParaTela("panel"); }
    function openTutorials() { if (!exigirPermissao("tutoriais")) return; irParaTela("tutorials"); }
    function openPortarias() { if (!exigirPermissao("portarias")) return; irParaTela("portarias"); }
    function openRegras() { if (!exigirPermissao("regras")) return; irParaTela("regras"); }
    function openComparativo() { if (!exigirPermissao("comparativo")) return; irParaTela("comparativo"); }
    function openCursos() { if (!exigirPermissao("cursos")) return; irParaTela("cursos"); }
    function backToWelcome() { irParaTela("welcome"); }
    function initTutorialsScreen() {
      renderTutCats();
      const chave = (tutCategoriaAtual && TUTORIAIS[tutCategoriaAtual]) ? tutCategoriaAtual : Object.keys(TUTORIAIS)[0];
      const btn = document.querySelector(`.tut-cat-btn[data-cat="${chave}"]`);
      if (btn) setTutCat(btn, chave);
    }
    function renderTutCats() {
      const cont = document.getElementById("tut-cats-list");
      if (!cont) return;
      let html = "";
      Object.keys(TUTORIAIS).forEach(key => {
        const cat = TUTORIAIS[key];
        const ativo = key === tutCategoriaAtual ? "active" : "";
        const delBtn = adminMode
          ? `<span class="tut-cat-del" data-del-cat="${key}" title="Excluir categoria">🗑️</span>`
          : "";
        html += `
          <button class="tut-cat-btn ${ativo}" data-cat="${key}">
            <span class="tut-cat-icon">${cat.icon || "📁"}</span> ${escapeHtmlRegra(cat.label || cat.titulo || key)}${delBtn}
          </button>`;
      });
      cont.innerHTML = html;
      cont.querySelectorAll(".tut-cat-btn").forEach(btn => {
        btn.addEventListener("click", (e) => {
          if (e.target.closest("[data-del-cat]")) return; // clique foi no lixinho, não troca de categoria
          setTutCat(btn, btn.getAttribute("data-cat"));
        });
      });
      cont.querySelectorAll("[data-del-cat]").forEach(el => {
        el.addEventListener("click", (e) => {
          e.stopPropagation();
          excluirTutCategoria(el.getAttribute("data-del-cat"));
        });
      });
    }
    function excluirTutCategoria(cat) {
      const data = TUTORIAIS[cat];
      if (!data) return;
      if (!confirm(`Excluir a categoria "${data.label || data.titulo || cat}" e todos os vídeos dela? Essa ação não pode ser desfeita.`)) return;
      delete TUTORIAIS[cat];
      resyncDataBlock("tutoriais", TUTORIAIS);
      const chaves = Object.keys(TUTORIAIS);
      renderTutCats();
      if (chaves.length) {
        const proxima = chaves[0];
        const btn = document.querySelector(`.tut-cat-btn[data-cat="${proxima}"]`);
        setTutCat(btn, proxima);
      } else {
        tutCategoriaAtual = null;
        document.getElementById("tut-content").innerHTML = `<div class="tut-empty">📂 Nenhuma categoria cadastrada ainda</div>`;
      }
    }
    history.replaceState({ tela: "welcome" }, "");
    window.addEventListener("popstate", (e) => {
      const tela = (e.state && e.state.tela) || "welcome";
      irParaTela(tela, false);
    });
    let cursosEstadoAtual = null;
    let cursosEstadosList = [];
    const CURSOS_UF_LABEL = {
      "Santa Catarina": "SANTA CATARINA"
    };
    function cursosUfLabel(uf) {
      return CURSOS_UF_LABEL[uf] || (uf || "").toUpperCase();
    }
    const CURSOS_ESTADO_REAL = {};
    function cursosEstadoReal(inst) {
      return CURSOS_ESTADO_REAL[inst.idinstituicao] || inst.estado;
    }
    function excluirCursoDeInstituicao(idinstituicao, idCurso, nomeCurso) {
      if (!adminMode) return;
      if (!confirm(`Remover o curso "${nomeCurso}" desta instituição?\n\n(O curso continua existindo — ele só deixa de aparecer para esta instituição. Dá pra desfazer depois em "Reexibir cursos removidos".)`)) return;
      const lista = CURSOS_EXCLUIDOS_POR_INST[idinstituicao] || (CURSOS_EXCLUIDOS_POR_INST[idinstituicao] = []);
      if (!lista.includes(idCurso)) lista.push(idCurso);
      resyncDataBlock("cursosexcluidos", CURSOS_EXCLUIDOS_POR_INST);
      const inst = DB.instituicoes.find(i => i.idinstituicao === idinstituicao);
      if (inst) selectCursosInst(idinstituicao, document.querySelector(`#cursos-inst-items .regras-item.active`));
    }
    function reexibirCursosDeInstituicao(idinstituicao) {
      if (!adminMode) return;
      if (!CURSOS_EXCLUIDOS_POR_INST[idinstituicao] || CURSOS_EXCLUIDOS_POR_INST[idinstituicao].length === 0) return;
      if (!confirm("Voltar a exibir todos os cursos removidos desta instituição?")) return;
      CURSOS_EXCLUIDOS_POR_INST[idinstituicao] = [];
      resyncDataBlock("cursosexcluidos", CURSOS_EXCLUIDOS_POR_INST);
      selectCursosInst(idinstituicao, document.querySelector(`#cursos-inst-items .regras-item.active`));
    }
    function initCursosScreen() {
      const estadosComInst = Array.from(new Set(DB.instituicoes.map(i => cursosEstadoReal(i)).filter(Boolean)));
      const estados = Array.from(new Set([...estadosComInst, ...CURSOS_ESTADOS_MANUAL]));
      estados.sort((a, b) => {
        const idsA = DB.instituicoes.filter(i => cursosEstadoReal(i) === a).map(i => i.idinstituicao);
        const idsB = DB.instituicoes.filter(i => cursosEstadoReal(i) === b).map(i => i.idinstituicao);
        const minA = idsA.length ? Math.min(...idsA) : Infinity;
        const minB = idsB.length ? Math.min(...idsB) : Infinity;
        return minA - minB;
      });
      cursosEstadosList = estados;
      cursosEstadoAtual = (cursosEstadoAtual && estados.includes(cursosEstadoAtual)) ? cursosEstadoAtual : (estados[0] || null);
      document.getElementById("cursos-inst-search").value = "";
      renderCursosEstados(estados);
      renderCursosInstList();
      document.getElementById("cursos-detail-pane").innerHTML = `
        <div class="regras-empty-state">
          <div class="icon">👈</div>
          <p>Selecione uma instituição para ver os cursos disponíveis</p>
        </div>`;
    }
    function adicionarEstadoCursos() {
      const nome = prompt("Nome do novo estado:", "");
      if (nome === null) return;
      const nomeLimpo = nome.trim();
      if (!nomeLimpo) { alert("Digite um nome para o estado."); return; }
      if (cursosEstadosList.includes(nomeLimpo)) { alert("Esse estado já existe na lista."); return; }
      CURSOS_ESTADOS_MANUAL.push(nomeLimpo);
      resyncDataBlock("cursosestados", CURSOS_ESTADOS_MANUAL);
      cursosEstadoAtual = nomeLimpo;
      initCursosScreen();
    }
    function excluirEstadoCursos(uf) {
      const qtd = DB.instituicoes.filter(i => cursosEstadoReal(i) === uf).length;
      const aviso = qtd > 0 ? ` Isso vai excluir também ${qtd} instituição(ões) cadastrada(s) nele.` : "";
      if (!confirm(`Excluir o estado "${cursosUfLabel(uf)}"?${aviso}`)) return;
      if (qtd > 0) {
        const idsRemover = DB.instituicoes.filter(i => cursosEstadoReal(i) === uf).map(i => i.idinstituicao);
        DB.instituicoes = DB.instituicoes.filter(i => !idsRemover.includes(i.idinstituicao));
        resyncDataBlock("db", DB);
      }
      CURSOS_ESTADOS_MANUAL.splice(CURSOS_ESTADOS_MANUAL.indexOf(uf), 1);
      resyncDataBlock("cursosestados", CURSOS_ESTADOS_MANUAL);
      cursosEstadoAtual = null;
      initCursosScreen();
    }
    function adicionarInstituicaoCursos() {
      if (!cursosEstadoAtual) { alert("Selecione ou adicione um estado primeiro."); return; }
      const mantenedoraPadrao = DB.mantenedoras[0];
      if (!mantenedoraPadrao) { alert("Cadastre uma mantenedora antes de adicionar instituições."); return; }
      const nome = prompt(`Nome da nova instituição em ${cursosUfLabel(cursosEstadoAtual)}:`, "");
      if (nome === null) return;
      const nomeLimpo = nome.trim() || "Nova instituição";
      const novoId = proximoId("instituicoes", "idinstituicao");
      DB.instituicoes.push({
        idinstituicao: novoId,
        idmantenedora: mantenedoraPadrao.idmantenedora,
        nome: nomeLimpo,
        nome_abreviado: nomeLimpo,
        estado: cursosEstadoAtual
      });
      resyncDataBlock("db", DB);
      initCursosScreen();
      selectCursosEstado(cursosEstadoAtual);
    }
    function renderCursosEstados(estados) {
      const cont = document.getElementById("cursos-estados-list");
      let html = "";
      estados.forEach((uf, idx) => {
        const qtd = DB.instituicoes.filter(i => cursosEstadoReal(i) === uf).length;
        const ativo = uf === cursosEstadoAtual ? "active" : "";
        const delBtn = adminMode
          ? `<span class="regras-cat-del" data-del-uf-idx="${idx}" title="Excluir estado">🗑️</span>`
          : "";
        html += `
          <button class="regras-cat-btn ${ativo}" data-uf-idx="${idx}">
            <span class="regras-cat-num">📍</span>
            <span class="regras-cat-label">${cursosUfLabel(uf)}</span>
            <span class="regras-cat-count">${qtd}</span>
            ${delBtn}
          </button>`;
      });
      cont.innerHTML = html || `<div class="regras-empty-list">Nenhum estado cadastrado</div>`;
      cont.querySelectorAll(".regras-cat-btn").forEach(btn => {
        btn.addEventListener("click", (e) => {
          if (e.target.closest("[data-del-uf-idx]")) return;
          const idx = Number(btn.getAttribute("data-uf-idx"));
          selectCursosEstado(cursosEstadosList[idx]);
        });
      });
      cont.querySelectorAll("[data-del-uf-idx]").forEach(el => {
        el.addEventListener("click", (e) => {
          e.stopPropagation();
          const idx = Number(el.getAttribute("data-del-uf-idx"));
          excluirEstadoCursos(cursosEstadosList[idx]);
        });
      });
    }
    function selectCursosEstado(uf) {
      cursosEstadoAtual = uf;
      document.querySelectorAll("#cursos-estados-list .regras-cat-btn").forEach(b => {
        const idx = Number(b.getAttribute("data-uf-idx"));
        b.classList.toggle("active", cursosEstadosList[idx] === uf);
      });
      document.getElementById("cursos-inst-search").value = "";
      renderCursosInstList();
      document.getElementById("cursos-detail-pane").innerHTML = `
        <div class="regras-empty-state">
          <div class="icon">👈</div>
          <p>Selecione uma instituição para ver os cursos disponíveis</p>
        </div>`;
    }
    function renderCursosInstList() {
      const q = document.getElementById("cursos-inst-search").value.trim().toLowerCase();
      const listEl = document.getElementById("cursos-inst-items");
      const titleEl = document.getElementById("cursos-inst-title");
      const countEl = document.getElementById("cursos-inst-count");
      let itens;
      if (q) {
        itens = DB.instituicoes.filter(i =>
          (i.nome_abreviado || "").toLowerCase().includes(q) ||
          (i.nome || "").toLowerCase().includes(q) ||
          (i.cidade || "").toLowerCase().includes(q));
        titleEl.textContent = `Resultados para "${q}"`;
      } else {
        itens = DB.instituicoes.filter(i => cursosEstadoReal(i) === cursosEstadoAtual);
        titleEl.textContent = cursosEstadoAtual ? cursosUfLabel(cursosEstadoAtual) : "Instituições";
      }
      countEl.textContent = itens.length + (itens.length === 1 ? " instituição" : " instituições");
      let html = "";
      itens.forEach(inst => {
        const qtdCursos = getCursosForInst(inst).length;
        const delBtn = adminMode
          ? `<span class="regras-item-del" data-del-inst="${inst.idinstituicao}" title="Excluir instituição">🗑️</span>`
          : "";
        html += `
          <div class="regras-item" onclick="selectCursosInst(${inst.idinstituicao}, this)">
            <div class="regras-item-icon">🏢</div>
            <div class="regras-item-info">
              <div class="regras-item-title">${inst.nome_abreviado || inst.nome}</div>
              <div class="regras-item-preview">${inst.cidade || "—"} · ${qtdCursos} curso${qtdCursos === 1 ? "" : "s"} disponíve${qtdCursos === 1 ? "l" : "is"}</div>
            </div>
            ${delBtn}
          </div>`;
      });
      listEl.innerHTML = html || `<div class="regras-empty-list">Nenhuma instituição encontrada</div>`;
      listEl.querySelectorAll("[data-del-inst]").forEach(el => {
        el.addEventListener("click", (e) => {
          e.stopPropagation();
          excluirRegistro("instituicoes", Number(el.getAttribute("data-del-inst")));
          initCursosScreen();
        });
      });
    }
    function selectCursosInst(idinstituicao, el) {
      document.querySelectorAll("#cursos-inst-items .regras-item.active").forEach(x => x.classList.remove("active"));
      if (el) el.classList.add("active");
      const inst = DB.instituicoes.find(i => i.idinstituicao === idinstituicao);
      if (!inst) return;
      activeCursoId = null;
      activeInstId = inst.idinstituicao;
      const cursos = getCursosForInst(inst);
      let html = `
        <div class="regras-detail-card">
          <div class="regras-detail-header">
            <div class="regras-detail-icon">🏢</div>
            <div>
              <div class="regras-detail-breadcrumb">${cursosEstadoReal(inst) || ""}${inst.cidade ? " · " + inst.cidade : ""}</div>
              <h2>${inst.nome_abreviado || inst.nome}</h2>
            </div>
          </div>
          <div class="cursos-section-header" style="margin-top:10px">
            📚 Cursos disponíveis &nbsp;<span style="font-size:10px;font-weight:400;color:var(--texto-muted)">(${cursos.length} cursos)</span>
            ${adminMode && (CURSOS_EXCLUIDOS_POR_INST[inst.idinstituicao] || []).length > 0
              ? `<button class="admin-danger-btn" style="margin-left:10px;font-size:10px;padding:3px 9px;" onclick="reexibirCursosDeInstituicao(${inst.idinstituicao})">↺ Reexibir cursos removidos (${CURSOS_EXCLUIDOS_POR_INST[inst.idinstituicao].length})</button>`
              : ""}
          </div>
          <div class="cursos-grid" id="cursos-grid">`;
      if (cursos.length === 0) {
        html += `<div class="extra-empty">Nenhum curso cadastrado para esta instituição</div>`;
      } else {
        cursos.forEach(curso => {
          html += `<div class="curso-btn-wrap" style="position:relative;display:inline-flex;">
            <button class="curso-btn" id="cbtn-${curso.id}" onclick="selectCurso(${curso.id}, this)">
              <span class="curso-id">#${curso.id}</span>
              ${curso.nome}
            </button>
            ${adminMode
              ? `<span class="regras-item-del" title="Excluir curso desta instituição"
                   style="position:absolute;top:-6px;right:-6px;background:#fff;border-radius:50%;box-shadow:0 1px 4px rgba(0,0,0,.18);"
                   onclick="event.stopPropagation(); excluirCursoDeInstituicao(${inst.idinstituicao}, ${curso.id}, '${(curso.nome || "").replace(/'/g, "\\'")}')">🗑️</span>`
              : ""}
          </div>`;
        });
      }
      html += `</div>
          <div id="curso-detail-area"></div>
        </div>`;
      document.getElementById("cursos-detail-pane").innerHTML = html;
    }
    const REGRAS_DATA = { categorias: [] };
    let regrasCategoriaAtual = null;
    function escapeHtmlRegra(txt) {
      return String(txt)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;");
    }
    function formatarConteudoRegra(txt) {
      if (!txt) return "";
      let esc = escapeHtmlRegra(txt);
      esc = esc.replace(/(https?:\/\/[^\s)]+)/g, url =>
        `<a href="${url}" target="_blank" rel="noopener" class="regras-link">${url}</a>`);
      esc = esc.replace(/\*(.+?)\*/g, "<strong>$1</strong>");
      const paragrafos = esc.split(/\n{2,}/).map(p => `<p>${p.replace(/\n/g, "<br>")}</p>`);
      return paragrafos.join("");
    }
    function initRegras() {
      const cats = REGRAS_DATA.categorias;
      document.getElementById("regras-search-input").value = "";
      if (!cats.length) {
        regrasCategoriaAtual = null;
        renderRegrasCats();
        document.getElementById("regras-list-title").textContent = "—";
        document.getElementById("regras-list-count").textContent = "";
        document.getElementById("regras-list-items").innerHTML = `<div class="regras-empty-list">Nenhum tópico cadastrado</div>`;
        document.getElementById("regras-detail-pane").innerHTML = `
          <div class="regras-empty-state">
            <div class="icon">👈</div>
            <p>Adicione um tópico para começar</p>
          </div>`;
        return;
      }
      regrasCategoriaAtual = cats[0].id;
      renderRegrasCats();
      renderRegrasList();
      document.getElementById("regras-detail-pane").innerHTML = `
        <div class="regras-empty-state">
          <div class="icon">👈</div>
          <p>Selecione um tópico para ver a mensagem</p>
        </div>`;
    }
    function renderRegrasCats() {
      const cont = document.getElementById("regras-cats-list");
      let html = "";
      REGRAS_DATA.categorias.forEach(cat => {
        const ativo = cat.id === regrasCategoriaAtual ? "active" : "";
        const delBtn = adminMode
          ? `<span class="regras-cat-del" data-del-topico="${cat.id}" title="Excluir tópico">🗑️</span>`
          : "";
        html += `
          <button class="regras-cat-btn ${ativo}" data-cat-id="${cat.id}">
            <span class="regras-cat-num">${cat.numero}</span>
            <span class="regras-cat-label">${cat.titulo}</span>
            <span class="regras-cat-count">${cat.itens.length}</span>
            ${delBtn}
          </button>`;
      });
      cont.innerHTML = html || `<div class="regras-empty-list">Nenhum tópico cadastrado</div>`;
      cont.querySelectorAll(".regras-cat-btn").forEach(btn => {
        btn.addEventListener("click", (e) => {
          if (e.target.closest("[data-del-topico]")) return;
          selectRegrasCategoria(btn.getAttribute("data-cat-id"));
        });
      });
      cont.querySelectorAll("[data-del-topico]").forEach(el => {
        el.addEventListener("click", (e) => {
          e.stopPropagation();
          excluirRegrasTopico(el.getAttribute("data-del-topico"));
        });
      });
    }
    function selectRegrasCategoria(id) {
      regrasCategoriaAtual = id;
      document.getElementById("regras-search-input").value = "";
      renderRegrasCats();
      renderRegrasList();
      document.getElementById("regras-detail-pane").innerHTML = `
        <div class="regras-empty-state">
          <div class="icon">👈</div>
          <p>Selecione um tópico para ver a mensagem</p>
        </div>`;
    }
    function abrirNovoRegrasTopico() {
      const nome = prompt("Nome do novo tópico:");
      if (nome === null) return;
      const nomeLimpo = nome.trim();
      if (!nomeLimpo) { alert("Digite um nome para o tópico."); return; }
      const maiorNumero = REGRAS_DATA.categorias.reduce((max, c) => Math.max(max, Number(c.numero) || 0), 0);
      const novoId = "topico-" + Date.now();
      REGRAS_DATA.categorias.push({
        id: novoId,
        numero: maiorNumero + 1,
        titulo: nomeLimpo,
        itens: []
      });
      syncRegrasDataScript();
      regrasCategoriaAtual = novoId;
      renderRegrasCats();
      renderRegrasList();
    }
    function excluirRegrasTopico(id) {
      const cat = REGRAS_DATA.categorias.find(c => c.id === id);
      if (!cat) return;
      if (!confirm(`Excluir o tópico "${cat.titulo}" e todas as ${cat.itens.length} mensagem(ns) dele? Essa ação não pode ser desfeita.`)) return;
      REGRAS_DATA.categorias = REGRAS_DATA.categorias.filter(c => c.id !== id);
      syncRegrasDataScript();
      initRegras();
    }
    function buildRegrasItemRow(cat, item, comCategoria, indice) {
      const label = item.subtitulo ? item.subtitulo : `Mensagem ${indice + 1}`;
      const previewBruto = item.conteudo.replace(/\s+/g, " ").trim();
      const preview = previewBruto.length > 90 ? previewBruto.slice(0, 90) + "…" : previewBruto;
      const delBtn = adminMode
        ? `<span class="regras-item-del" data-del-msg-cat="${cat.id}" data-del-msg-item="${item.id}" title="Excluir mensagem">🗑️</span>`
        : "";
      return `
        <div class="regras-item" onclick="selectRegrasItem('${cat.id}','${item.id}',this)">
          <div class="regras-item-icon">${item.subtitulo ? "📌" : "💬"}</div>
          <div class="regras-item-info">
            ${comCategoria ? `<div class="regras-item-cat">${cat.numero}. ${cat.titulo}</div>` : ""}
            <div class="regras-item-title">${escapeHtmlRegra(label)}</div>
            <div class="regras-item-preview">${escapeHtmlRegra(preview)}</div>
          </div>
          ${delBtn}
        </div>`;
    }
    function renderRegrasList() {
      const q = document.getElementById("regras-search-input").value.trim().toLowerCase();
      const listEl = document.getElementById("regras-list-items");
      const titleEl = document.getElementById("regras-list-title");
      const countEl = document.getElementById("regras-list-count");
      let html = "";
      let count = 0;
      if (!REGRAS_DATA.categorias.length) {
        titleEl.textContent = "—";
        countEl.textContent = "";
        listEl.innerHTML = `<div class="regras-empty-list">Nenhum tópico cadastrado</div>`;
        return;
      }
      if (q) {
        REGRAS_DATA.categorias.forEach(cat => {
          cat.itens.forEach((item, idx) => {
            const alvo = `${cat.titulo} ${item.subtitulo || ""} ${item.conteudo}`.toLowerCase();
            if (!alvo.includes(q)) return;
            count++;
            html += buildRegrasItemRow(cat, item, true, idx);
          });
        });
        titleEl.textContent = `Resultados para "${q}"`;
      } else {
        const cat = REGRAS_DATA.categorias.find(c => c.id === regrasCategoriaAtual) || REGRAS_DATA.categorias[0];
        regrasCategoriaAtual = cat.id;
        titleEl.textContent = `${cat.numero}. ${cat.titulo}`;
        cat.itens.forEach((item, idx) => {
          count++;
          html += buildRegrasItemRow(cat, item, false, idx);
        });
      }
      countEl.textContent = count + (count === 1 ? " item" : " itens");
      listEl.innerHTML = html || `<div class="regras-empty-list">Nenhum resultado encontrado</div>`;
      listEl.querySelectorAll("[data-del-msg-cat]").forEach(el => {
        el.addEventListener("click", (e) => {
          e.stopPropagation();
          excluirRegrasMensagem(el.getAttribute("data-del-msg-cat"), el.getAttribute("data-del-msg-item"));
        });
      });
    }
    function abrirNovaRegrasMensagem() {
      if (!regrasCategoriaAtual) { alert("Crie ou selecione um tópico primeiro."); return; }
      const cat = REGRAS_DATA.categorias.find(c => c.id === regrasCategoriaAtual);
      if (!cat) return;
      const novoId = "msg-" + Date.now();
      cat.itens.push({ id: novoId, subtitulo: null, conteudo: "" });
      syncRegrasDataScript();
      renderRegrasCats();
      renderRegrasList();
      const el = document.querySelector(`#regras-list-items .regras-item[onclick*="'${novoId}'"]`);
      abrirEdicaoRegra(cat.id, novoId);
      if (el) el.classList.add("active");
    }
    function excluirRegrasMensagem(catId, itemId) {
      const cat = REGRAS_DATA.categorias.find(c => c.id === catId);
      const item = cat && cat.itens.find(i => i.id === itemId);
      if (!item) return;
      if (!confirm(`Excluir a mensagem "${item.subtitulo || "sem subtítulo"}"?`)) return;
      cat.itens = cat.itens.filter(i => i.id !== itemId);
      syncRegrasDataScript();
      renderRegrasCats();
      renderRegrasList();
      document.getElementById("regras-detail-pane").innerHTML = `
        <div class="regras-empty-state">
          <div class="icon">👈</div>
          <p>Selecione um tópico para ver a mensagem</p>
        </div>`;
    }
    function selectRegrasItem(catId, itemId, el) {
      document.querySelectorAll("#regras-list-items .regras-item.active")
        .forEach(x => x.classList.remove("active"));
      if (el) el.classList.add("active");
      const cat = REGRAS_DATA.categorias.find(c => c.id === catId);
      const item = cat && cat.itens.find(i => i.id === itemId);
      if (!item) return;
      const html = `
        <div class="regras-detail-card">
          <div class="regras-detail-header">
            <div class="regras-detail-icon">${item.subtitulo ? "📌" : "💬"}</div>
            <div>
              <div class="regras-detail-breadcrumb">${cat.numero}. ${cat.titulo}</div>
              <h2>${escapeHtmlRegra(item.subtitulo || "Mensagem padrão")}</h2>
            </div>
            <button class="regras-copy-btn" id="regras-copy-btn" onclick="copiarRegraMsg('${catId}','${itemId}', this)">
              📋 Copiar mensagem
            </button>
          </div>
          <div class="regras-detail-content">${formatarConteudoRegra(item.conteudo)}</div>
        </div>`;
      document.getElementById("regras-detail-pane").innerHTML = html;
    }
    function converterNegritoParaColchetes(txt) {
      return String(txt).replace(/\*(.+?)\*/g, "[b]$1[/b]");
    }
    function copiarRegraMsg(catId, itemId, btn) {
      const cat = REGRAS_DATA.categorias.find(c => c.id === catId);
      const item = cat && cat.itens.find(i => i.id === itemId);
      if (!item) return;
      const textoParaCopiar = converterNegritoParaColchetes(item.conteudo);
      const finalizarCopia = () => {
        const original = btn.innerHTML;
        btn.innerHTML = "✅ Copiado!";
        btn.classList.add("copied");
        setTimeout(() => {
          btn.innerHTML = original;
          btn.classList.remove("copied");
        }, 1800);
      };
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(textoParaCopiar).then(finalizarCopia).catch(() => {
          fallbackCopiarTexto(textoParaCopiar);
          finalizarCopia();
        });
      } else {
        fallbackCopiarTexto(textoParaCopiar);
        finalizarCopia();
      }
    }
    function fallbackCopiarTexto(texto) {
      const ta = document.createElement("textarea");
      ta.value = texto;
      ta.style.position = "fixed";
      ta.style.opacity = "0";
      document.body.appendChild(ta);
      ta.select();
      try { document.execCommand("copy"); } catch (e) {  }
      document.body.removeChild(ta);
    }
